'use strict';
(function(root){const images=new Map;function image(n){if(!images.has(n)){const im=new Image;im.src='rpg-fx/'+n+'.png';images.set(n,im);}return images.get(n);}const pi=Math.PI,colors={fire:'#ef9a51',ice:'#a2e4ed',storm:'#dbcbff'};
function line(p,x1,y1,x2,y2,c,w=2){p.strokeStyle=c;p.lineWidth=w;p.beginPath();p.moveTo(x1,y1);p.lineTo(x2,y2);p.stroke();}
function diamond(p,x,y,r,c){p.fillStyle=c;p.beginPath();p.moveTo(x,y-r);p.lineTo(x+r,y);p.lineTo(x,y+r);p.lineTo(x-r,y);p.closePath();p.fill();}
function casing(p,x,y,angle=0,size=9){p.save();p.translate(x,y);p.rotate(angle);p.fillStyle='#816340';p.fillRect(-size/2,-2,size,4);p.fillStyle='#ead39a';p.fillRect(-size/2,-2,size,2);p.restore();}
function bullet(p,b){p.save();p.translate(b.x,b.y);p.rotate(b.angle);if(['rocket','concussion','demolition','small-rocket','siege'].includes(b.kind)){const size=b.kind==='demolition'?42:b.kind==='siege'?35:b.kind==='small-rocket'?20:29;p.fillStyle=b.kind==='siege'?'#bac8cc':'#c5ae79';p.fillRect(-size*.6,-5,size,10);p.fillStyle='#53646c';p.fillRect(-size*.55,-5,size*.65,3);p.fillStyle='#f3dfb4';p.beginPath();p.moveTo(size*.4,-5);p.lineTo(size*.7,0);p.lineTo(size*.4,5);p.fill();p.fillStyle='#e69554';p.fillRect(-size*.8,-2,size*.25,4);if(b.kind!=='siege'){line(p,-size*.3,-5,-size*.7,-11,'#788d96',3);line(p,-size*.3,5,-size*.7,11,'#788d96',3);}}else if(b.kind.startsWith('rune')||b.kind==='resonance'||b.element){const c=colors[b.element]||'#b0dcdd';if(b.element==='storm'){line(p,-18,-5,-5,3,c,3);line(p,-5,3,-9,-4,c,3);line(p,-9,-4,11,0,c,3);}else if(b.element==='ice'){diamond(p,0,0,10,c);diamond(p,0,0,4,'#f2ffff');}else if(b.element==='fire'){p.fillStyle=c;p.fillRect(-16,-3,18,6);diamond(p,5,0,8,'#ffe1a1');}else{diamond(p,0,0,b.kind==='rune-break'?14:8,c);line(p,-20,0,4,0,'#f5eed7',3);}}else{const size=b.kind==='pellet'?6:b.kind==='precision'?20:14;p.fillStyle=b.kind==='dance-round'?'#eab88f':'#e9dbac';p.fillRect(-size,-1.5,size,3);p.fillStyle='#ffffeb';p.fillRect(-5,-1,5,2);}p.restore();}
function shell(p,s){const q=Math.min(1,s.time/s.duration),x=s.from.x+(s.to.x-s.from.x)*q,y=s.from.y+(s.to.y-s.from.y)*q-Math.sin(q*pi)*(s.kind==='grenade'?75:160),a=Math.atan2((s.to.y-s.from.y)-Math.cos(q*pi)*pi*160,s.to.x-s.from.x);p.save();p.translate(x,y);p.rotate(a);if(s.kind==='grenade'){p.fillStyle='#314a46';p.fillRect(-7,-6,14,12);p.fillStyle='#829b7a';p.fillRect(-5,-5,9,3);p.fillStyle='#e7bf77';p.fillRect(-9,-2,3,4);}else{const im=image('shell-authored');if(im.complete&&im.naturalWidth)p.drawImage(im,418,246,1141,302,-(s.kind==='bomblet'?11:22),-5,s.kind==='bomblet'?22:44,10);}p.restore();}
function crosshair(p,x,y,size,time,color='#b5c8a4'){p.save();p.translate(x,y);p.strokeStyle=color;p.lineWidth=2;for(const side of [-1,1]){line(p,side*size,-8,side*size,-size*.45,color);line(p,side*size,-size*.45,side*(size-10),-size*.45,color);line(p,side*size,8,side*size,size*.45,color);line(p,side*size,size*.45,side*(size-10),size*.45,color);}diamond(p,0,0,3,color);p.restore();}
function cannon(p,c,k,time){const im=image('gunner-siege-cannon');if(!k.emplacement||!im.complete||!im.naturalWidth)return;p.save();p.translate(c.x,c.y+12);if(c.facing)p.scale(-1,1);const recoil=time-(c.lastBasic??-99)<.15?-4:0;p.imageSmoothingEnabled=false;p.drawImage(im,19,128,1487,804,-34+recoil,-53,120,65);p.restore();}
function draw(p,f,t,D){if(f.heroId!==9)return false;if(t<0||t>1.5)return true;const a=D?.skills.find(s=>s.heroId===9&&s.cell===f.cell&&s.slot===f.slot)?.actions[0],kind=f.gunnerKind||a?.kind,o=f.from||f,F=root.RPG_SKILL_FX;p.save();p.globalAlpha*=Math.max(0,1-t/1.4);const x=f.x,y=f.y-20;
if(f.phase){switch(kind){case'muzzle':{const n=f.weapon==='siege'?60:22,angle=f.angle||0,px=o.x+Math.cos(angle)*n,py=o.y+Math.sin(angle)*n;p.save();p.translate(px,py);p.rotate(angle);p.fillStyle='#ffe8b2';p.beginPath();p.moveTo(0,-5);p.lineTo(17,-9);p.lineTo(11,0);p.lineTo(20,6);p.lineTo(0,4);p.fill();p.restore();break;}case'magazine':for(let i=0;i<3;i++)casing(p,o.x-16-i*8-t*15,o.y+10+t*25,t*5+i);break;case'bullet-hit':F?.sheet(p,'spark',t,.35,x,y,28,25);break;case'rocket-impact':F?.sheet(p,f.radius>100?'heavy':'blast',t,.85,x,y,f.radius*1.8,f.radius*1.4);F?.sheet(p,'dust',t-.12,.7,x,y+20,f.radius*1.5,40);break;case'armor-impact':F?.sheet(p,'shock',t,.65,x,y,95,65);for(let i=0;i<5;i++)line(p,x,y,x+(i-2)*22,y-20-t*20,'#d9cda6',2);break;case'rune-fire':F?.sheet(p,'blast',t,.55,x,y,65,55);break;case'rune-ice':for(let i=0;i<5;i++)diamond(p,x+(i-2)*12,y-Math.sin(t*pi)*30,4+i%2*3,'#b5e8ed');break;case'rune-storm':for(const v of f.targets||[{x:x+40,y:y-20}]){const mx=(x+v.x)/2;line(p,x,y,mx+8,(y+v.y-20)/2-12,'#e1d8ff',3);line(p,mx+8,(y+v.y-20)/2-12,v.x,v.y-20,'#aabce4',3);}break;case'mortar-launch':F?.sheet(p,'dust',t,.6,o.x,o.y+25,70,25);break;case'shell-impact':F?.sheet(p,f.shell==='carpet'?'heavy':'blast',t,.9,x,y,(f.radius||80)*1.8,(f.radius||80)*1.4);F?.earth(p,x,y+22,t-.1,(f.radius||80)*.6,3);break;case'steam':F?.smoke(p,o.x-20,o.y+8,t,70,.6);F?.smoke(p,o.x+25,o.y,t+.1,50,.45);break;case'siege-recoil':F?.sheet(p,'dust',t,.7,o.x-20,o.y+32,130,40);F?.sheet(p,'shock',t,.5,o.x+50,o.y,75,50);break;}p.restore();return true;}
// Short weapon-specific preparation tells; moving projectiles are drawn from engine state.
switch(kind){case'revolver-shot':casing(p,o.x+20,o.y-5,-.2,13);break;case'buckshot':for(let i=0;i<5;i++)line(p,o.x+20,o.y-15,o.x+40,o.y-28+i*6,'#edcea0',2);break;case'cylinder-reload':for(let i=0;i<6;i++){const z=i*pi/3;diamond(p,o.x+Math.cos(z)*15,o.y-20+Math.sin(z)*15,3,'#d6ba80');}break;case'hand-grenade':p.fillStyle='#728c65';p.fillRect(o.x+17,o.y-25,10,12);break;case'crossfire':casing(p,o.x+18,o.y-28,-.5,17);casing(p,o.x+18,o.y-15,.5,17);break;case'precision-salvo':crosshair(p,x,y,22,t);break;case'speed-loader':for(let i=0;i<4;i++)casing(p,o.x-20+i*10,o.y-20+t*15,pi/2,12);break;case'deadeye':crosshair(p,x,y,36,t,'#e2c38d');line(p,x-48,y,x+48,y,'#c2d9df',1);break;case'explosive-rocket':casing(p,o.x+30,o.y-18,0,35);break;case'concussion-rocket':crosshair(p,x,y,20,t,'#a7d0d3');line(p,x-10,y+15,x+10,y+15,'#dce6d2',3);break;case'shoulder-aim':line(p,o.x+25,o.y-25,o.x+50,o.y-25,'#c3d6d3',2);diamond(p,o.x+35,o.y-35,6,'#cddfcf');break;case'demolition-rocket':casing(p,o.x+30,o.y-20,-.15,48);F?.sheet(p,'dust',t,.6,o.x-15,o.y+15,55,25);break;case'rough-triple':for(let i=0;i<3;i++)casing(p,o.x+20+i*6,o.y-26+i*7,-.2,12);break;case'death-circle':for(let i=0;i<8;i++){const z=i*pi/4;casing(p,o.x+Math.cos(z)*35,o.y-20+Math.sin(z)*20,z,8);}break;case'combat-loader':for(let i=0;i<2;i++)casing(p,o.x-30-i*10,o.y-10+t*20,t+i);line(p,o.x-35,o.y+10,o.x-15,o.y+10,'#bfd4c6',2);break;case'bullet-dance':for(let i=0;i<6;i++){const z=i*pi/3+t*2;casing(p,o.x+Math.cos(z)*42,o.y-20+Math.sin(z)*22,z,14);}break;case'inscribed-round':diamond(p,o.x+23,o.y-20,8,'#b4ded7');break;case'element-magazine':for(let i=0;i<3;i++)diamond(p,o.x-15+i*15,o.y-36,5,colors[['fire','ice','storm'][i]]);break;case'rune-resonance':for(let i=0;i<4;i++)diamond(p,x+(i%2?14:-14),y+(i<2?-14:14),4,'#c6c5e8');break;case'rune-breaker':diamond(p,o.x+30,o.y-22,14,'#daf4ef');line(p,o.x+5,o.y-22,o.x+45,o.y-22,'#e7d0ab',3);break;case'howitzer':crosshair(p,x,y,30,t);break;case'cluster-shell':for(let i=0;i<4;i++){const z=i*pi/2;diamond(p,x+Math.cos(z)*30,y+Math.sin(z)*15,4,'#cab58b');}break;case'fire-coordinates':crosshair(p,x,y,65,t,'#c6cdab');break;case'carpet-bombing':for(let i=0;i<9;i++)p.strokeRect(x+(i%3-1)*30-7,y+(Math.floor(i/3)-1)*20-4,14,8);break;case'deploy-cannon':line(p,o.x-30,o.y+20,o.x-40,o.y+30,'#c2a56c',5);line(p,o.x+30,o.y+20,o.x+40,o.y+30,'#c2a56c',5);break;case'piercing-cannon':casing(p,o.x+45,o.y-15,0,42);line(p,o.x+25,o.y-25,o.x+60,o.y-25,'#d5d9c4',2);break;case'emergency-vent':F?.smoke(p,o.x-20,o.y,t,45,.4);break;case'superheavy-shot':for(let i=0;i<3;i++)diamond(p,o.x+45+i*10,o.y-20,7-i,'#f6d7a2');F?.sheet(p,'dust',t,.8,o.x-10,o.y+22,80,25);break;}
p.restore();return true;}
function ground(p,g,time){if(g.s.active!==9||!g.c.gunner)return;const k=g.c.gunner;p.save();if(k.coordinates){crosshair(p,k.coordinates.x,k.coordinates.y,100,time,'#bdc8a4');for(let i=-1;i<=1;i++)line(p,k.coordinates.x-80,k.coordinates.y+i*25,k.coordinates.x+80,k.coordinates.y+i*25,'#65775e',1);}for(const s of k.shells){p.globalAlpha=.35;crosshair(p,s.to.x,s.to.y,s.kind==='bomblet'?14:24,time,'#c2a578');}p.restore();}
function state(p,g,time){if(g.s.active!==9||!g.c.gunner)return;const k=g.c.gunner,c=g.c;p.save();cannon(p,c,k,time);for(const b of k.bolts)bullet(p,b);for(const s of k.shells)shell(p,s);for(const e of c.enemies)if(e.hp>0&&e.gunMark>0)for(let i=0;i<e.gunMark;i++)diamond(p,e.x-8+i*8,e.y-58,3,'#b9d9d3');if(k.charges.length)for(let i=0;i<k.charges.length;i++)diamond(p,c.x-12+i*12,c.y-64,4,colors[k.charges[i]]);p.font='bold 9px sans-serif';p.textAlign='center';p.fillStyle='#efdbab';let text='';if([0,1,3].includes(g.h.cell))text=c.reloadTime>0?'재장전 '+c.reloadTime.toFixed(1)+'초':'탄창 '+c.meters.ammo+'/'+(g.h.cell===3?12:g.h.cell===1?8:6);if(g.h.cell===1)text+=' · 집중 '+k.focus;if(g.h.cell===6)text=(k.emplacement?'공성 · ':'')+'열기 '+Math.ceil(k.heat)+(k.overheat>0?' · 과열':'');if(g.h.cell===4)text='속성탄 '+k.charges.length+'/3';if(text)p.fillText(text,c.x,c.y-74);if(k.overheat>0)root.RPG_SKILL_FX?.smoke(p,c.x+25,c.y-8,time%.8,35,.35);p.restore();}
image('gunner-siege-cannon');image('shell-authored');root.RPG_GUNNER_FX={draw,state,ground};})(typeof window!=='undefined'?window:globalThis);
